package com.edib.workknowledge.comparison

import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Structural comparison of two real workbook revisions.
 *
 * The fixtures are generated by make_revision_fixtures.py with known
 * differences, and each expected difference is asserted on its own so a single
 * regression cannot hide behind the others.
 */
class StructuralWorkbookDiffTest {

    private val reader = WorkbookSnapshotReader()
    private val differ = StructuralWorkbookDiff()

    private fun fixture(name: String): ByteArray {
        val stream = javaClass.classLoader!!.getResourceAsStream("fixtures/$name")
            ?: error("fixture not on classpath: $name")
        return stream.use { it.readBytes() }
    }

    private fun diffRevisions(): WorkbookDiff = runBlocking {
        val r1 = reader.use {
            it.open(fixture("WK_BOQ_Rev01.xlsx"))
            it.snapshot("WK_BOQ_Rev01.xlsx")
        }
        val r2 = reader.use {
            it.open(fixture("WK_BOQ_Rev02.xlsx"))
            it.snapshot("WK_BOQ_Rev02.xlsx")
        }
        differ.diff(r1, r2)
    }

    // ------------------------------------------------------------ snapshots

    @Test
    fun `snapshot exposes sheets, headers and stable keys`() = runBlocking {
        val snap = reader.use {
            it.open(fixture("WK_BOQ_Rev01.xlsx"))
            it.snapshot("WK_BOQ_Rev01.xlsx")
        }
        assertEquals(setOf("Master Bathroom", "Ceilings", "Store Room"), snap.sheetNames)

        val master = snap.sheet("Master Bathroom")!!
        assertEquals("Item Code", master.headers.first())
        assertEquals("Item Code", master.keyColumn)
        assertEquals(1, master.headerRowNumber)
        // Row 1 is the header, so the first item is on sheet row 2.
        assertEquals(2, master.rows.first().rowNumber)
        assertEquals("MR-104", master.rows.first().key)
    }

    @Test
    fun `snapshot keeps formulas and coordinates`() = runBlocking {
        val snap = reader.use {
            it.open(fixture("WK_BOQ_Rev01.xlsx"))
            it.snapshot("WK_BOQ_Rev01.xlsx")
        }
        val row = snap.sheet("Master Bathroom")!!.rowByKey("MR-104")!!
        val amount = row.value("Amount")!!
        assertNotNull("the formula must survive", amount.formula)
        assertEquals("D2*E2", amount.formula)
        assertEquals("F2", amount.coordinate)
        assertEquals(37.5, row.value("Quantity")!!.numericValue!!, 1e-9)
    }

    @Test
    fun `units are captured as their own column`() = runBlocking {
        val snap = reader.use {
            it.open(fixture("WK_BOQ_Rev01.xlsx"))
            it.snapshot("WK_BOQ_Rev01.xlsx")
        }
        assertEquals("m2", snap.sheet("Master Bathroom")!!.rowByKey("MR-104")!!.value("Unit")!!.displayValue)
    }

    // ------------------------------------------------------------ diffs

    @Test
    fun `MR-104 quantity change is detected with numeric values`() {
        val change = diffRevisions().changedCells
            .single { it.sheet == "Master Bathroom" && it.key == "MR-104" && it.column == "Quantity" }
        assertEquals(ChangeKind.VALUE, change.kind)
        assertEquals(37.5, change.oldValue!!, 1e-9)
        assertEquals(42.0, change.newValue!!, 1e-9)
    }

    @Test
    fun `MR-105 rate change is detected`() {
        val change = diffRevisions().changedCells
            .single { it.sheet == "Master Bathroom" && it.key == "MR-105" && it.column == "Rate" }
        assertEquals(ChangeKind.VALUE, change.kind)
        assertEquals(2400.0, change.oldValue!!, 1e-9)
        assertEquals(2550.0, change.newValue!!, 1e-9)
    }

    @Test
    fun `CL-201 description change is detected`() {
        val change = diffRevisions().changedCells
            .single { it.sheet == "Ceilings" && it.key == "CL-201" && it.column == "Description" }
        assertEquals(ChangeKind.VALUE, change.kind)
        assertEquals("Gypsum Board Ceiling", change.oldDisplay)
        assertEquals("Gypsum Board Ceiling Board", change.newDisplay)
    }

    @Test
    fun `formula change is reported even when the value is unchanged`() {
        val change = diffRevisions().changedCells
            .single { it.sheet == "Master Bathroom" && it.key == "MR-120" && it.column == "Amount" }
        assertTrue(
            "a changed formula must be reported, got ${change.kind}",
            change.kind == ChangeKind.FORMULA || change.kind == ChangeKind.FORMULA_AND_VALUE
        )
        assertNotNull(change.detail)
        assertTrue(change.detail!!.contains("D5*E5"))
        assertTrue(change.detail!!.contains("D5*E5*1.05"))
    }

    @Test
    fun `a formula change shows the formulas, not their cached values`() {
        // The fixture has no calculated results, so both cached values are "0".
        // Rendering "0 -> 0" would tell the user nothing; the formulas must show.
        val change = diffRevisions().changedCells.single { it.key == "MR-120" }
        assertEquals("Amount", change.column)
        val described = change.describe()
        assertTrue(
            "a formula change must render the formulas, got: $described",
            described.contains("D5*E5") && described.contains("D5*E5*1.05")
        )
        assertFalse("a meaningless 0 -> 0 must not be shown", described.contains("0 -> 0"))
    }

    @Test
    fun `unchanged rows are not reported`() {
        val keys = diffRevisions().changedCells.mapNotNull { it.key }.toSet()
        assertFalse("MR-110 is identical in both revisions", keys.contains("MR-110"))
        // MR-104 changed only in Quantity; its other columns must be quiet.
        val mr104Changes = diffRevisions().changedCells
            .filter { it.key == "MR-104" }
            .map { it.column }
        assertEquals(listOf("Quantity"), mr104Changes)
    }

    @Test
    fun `numeric formatting alone is not a change`() {
        // 2400 and 2400.0 are the same rate; the snapshot stores a Double, so a
        // formatting-only difference must not surface.
        val before = SheetSnapshot(
            name = "S", index = 0,
            headers = listOf("Item Code", "Rate"), headerRowNumber = 1,
            rows = listOf(
                RowSnapshot(2, "X-1", mapOf(
                    "Item Code" to CellSnapshot("Item Code", 0, "A2", "X-1", null, null, CellType.TEXT),
                    "Rate" to CellSnapshot("Rate", 1, "B2", "2400", null, 2400.0, CellType.NUMBER)
                ))
            )
        )
        val after = before.copy(rows = listOf(
            before.rows.first().copy(cells = before.rows.first().cells.toMutableMap().apply {
                put("Rate", CellSnapshot("Rate", 1, "B2", "2400.0", null, 2400.0, CellType.NUMBER))
            })
        ))
        val diff = differ.diff(
            WorkbookSnapshot("a.xlsx", listOf(before)),
            WorkbookSnapshot("b.xlsx", listOf(after))
        )
        assertTrue("2400 and 2400.0 are the same number", diff.isEmpty)
    }

    @Test
    fun `removed row is detected`() {
        val removed = diffRevisions().removedRows
        assertEquals(1, removed.size)
        assertEquals("SR-301", removed.first().key)
        assertEquals("Master Bathroom", removed.first().sheet)
        assertTrue(removed.first().describe().contains("Sanitary Ware Set"))
    }

    @Test
    fun `added row is detected`() {
        val added = diffRevisions().addedRows
        assertEquals(1, added.size)
        assertEquals("MR-140", added.first().key)
        assertTrue(added.first().describe().contains("Travertine"))
    }

    @Test
    fun `added and removed sheets are detected`() {
        val diff = diffRevisions()
        assertEquals(listOf("Balcony"), diff.addedSheets)
        assertEquals(listOf("Store Room"), diff.removedSheets)
    }

    @Test
    fun `row numbers point at the real sheet rows`() = runBlocking {
        // MR-104 is the first data row, so it must be sheet row 2 in both
        // revisions; a viewer showing row 2 shows the changed item.
        val old = reader.use {
            it.open(fixture("WK_BOQ_Rev01.xlsx"))
            it.snapshot("WK_BOQ_Rev01.xlsx")
        }
        assertEquals(2, old.sheet("Master Bathroom")!!.rowByKey("MR-104")!!.rowNumber)
        // SR-301 is the fifth item, so sheet row 6.
        assertEquals(6, old.sheet("Master Bathroom")!!.rowByKey("SR-301")!!.rowNumber)
    }

    @Test
    fun `no relocation is reported when row order is stable`() {
        assertTrue(
            "rows did not move, so no relocation should be reported",
            diffRevisions().relocations.isEmpty()
        )
    }

    @Test
    fun `a moved row is reported as a relocation, not a content change`() = runBlocking {
        val before = SheetSnapshot(
            name = "S", index = 0,
            headers = listOf("Item Code", "Description"), headerRowNumber = 1,
            rows = listOf(
                RowSnapshot(2, "A-1", mapOf("Item Code" to textCell("A2", "A-1"), "Description" to textCell("B2", "First"))),
                RowSnapshot(3, "B-1", mapOf("Item Code" to textCell("A3", "B-1"), "Description" to textCell("B3", "Second")))
            )
        )
        val after = before.copy(rows = listOf(
            // same items, swapped rows
            before.rows[1].copy(rowNumber = 2, cells = mapOf("Item Code" to textCell("A2", "B-1"), "Description" to textCell("B2", "Second"))),
            before.rows[0].copy(rowNumber = 3, cells = mapOf("Item Code" to textCell("A3", "A-1"), "Description" to textCell("B3", "First")))
        ))
        val diff = differ.diff(
            WorkbookSnapshot("a.xlsx", listOf(before)),
            WorkbookSnapshot("b.xlsx", listOf(after))
        )
        assertEquals(2, diff.relocations.size)
        assertTrue(
            "a move must not be reported as an added or removed item",
            diff.addedRows.isEmpty() && diff.removedRows.isEmpty()
        )
    }

    @Test
    fun `description is never used as a row key`() {
        // Two items can share a description; matching on it would mispair them.
        val sheet = SheetSnapshot(
            name = "S", index = 0,
            headers = listOf("Description", "Quantity"), headerRowNumber = 1,
            rows = listOf(
                RowSnapshot(2, null, mapOf("Description" to text("A2", "Marble"))),
                RowSnapshot(3, null, mapOf("Description" to text("A3", "Marble")))
            )
        )
        assertNull("a Description column is not an identity column", sheet.keyColumn)
    }

    @Test
    fun `missing key column is reported rather than guessed`() {
        val sheet = SheetSnapshot(
            name = "S", index = 0,
            headers = listOf("Something", "Else"), headerRowNumber = 1,
            rows = emptyList()
        )
        assertNull(sheet.keyColumn)
    }

    @Test
    fun `diff summary is human readable`() {
        val summary = diffRevisions().summary()
        assertTrue(summary.contains("cell(s) changed"))
        assertFalse(diffRevisions().isEmpty)
    }

    private fun text(coordinate: String, value: String) =
        CellSnapshot("Description", 0, coordinate, value, null, null, CellType.TEXT)

    private fun textCell(coordinate: String, value: String) =
        CellSnapshot("Item Code", 0, coordinate, value, null, null, CellType.TEXT)
}
